import {
  Group,
  PlaneGeometry,
  MeshBasicMaterial,
  Mesh,
  DoubleSide,
  EdgesGeometry,
  LineSegments,
  LineBasicMaterial,
  Vector3
} from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const behaviorSpec = config.behaviorSpec || {};
  const interactions = behaviorSpec.interactions || [];
  const scenePosition = config.scenePosition || new Vector3(2.5, 1.6, 0);
  const sceneRotation = config.sceneRotation || { x: 0, y: 0, z: 0 };
  const sceneScale = config.sceneScale || { x: 1, y: 1, z: 1 };
  const colors = config.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // Size from image aspect (512x320 -> 1.6:1)
  const width = 1.6;
  const height = 1.0;

  // Main plane
  const geometry = new PlaneGeometry(width, height);
  const texture = ctx.textureLoader.load(config.assets.imageUrl);
  const material = new MeshBasicMaterial({
    map: texture,
    side: DoubleSide,
    toneMapped: true
  });
  const plane = new Mesh(geometry, material);
  plane.position.copy(scenePosition);
  plane.rotation.set(sceneRotation.x, sceneRotation.y, sceneRotation.z);
  plane.scale.set(sceneScale.x, sceneScale.y, sceneScale.z);

  // Accent edge (thin line)
  const edgeGeometry = new EdgesGeometry(new PlaneGeometry(width + 0.02, height + 0.02));
  const edgeMaterial = new LineBasicMaterial({ color: colors.accent });
  const edge = new LineSegments(edgeGeometry, edgeMaterial);
  edge.visible = false;
  plane.add(edge);

  // Group to return
  const group = new Group();
  group.add(plane);
  group.position.copy(scenePosition);
  group.rotation.set(sceneRotation.x, sceneRotation.y, sceneRotation.z);
  group.scale.set(sceneScale.x, sceneScale.y, sceneScale.z);

  // Interaction handlers
  group.userData.handlers = {};

  // GSAP timelines
  let hoverTimeline = null;
  let pressTween = null;

  // Hover: rise-in effect (0.15 units)
  const handlePointerEnter = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(plane.position, {
      y: scenePosition.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
      overwrite: 'auto'
    });
    edge.visible = true;
  };

  const handlePointerLeave = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(plane.position, {
      y: scenePosition.y,
      duration: 0.7,
      ease: 'power3.out',
      overwrite: 'auto'
    });
    edge.visible = false;
  };

  // Click: press-down and emit event
  const handlePointerDown = () => {
    pressTween = gsap.to(plane.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out',
      overwrite: 'auto'
    });
  };

  const handlePointerUp = () => {
    if (pressTween) {
      pressTween.kill();
      pressTween = null;
    }
    gsap.to(plane.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.12,
      ease: 'back.out',
      overwrite: 'auto'
    });
    // Emit event
    if (typeof group.userData.handlers.select === 'function') {
      group.userData.handlers.select();
    }
    const event = new CustomEvent('hub-journal-select', { detail: { node: group } });
    group.dispatchEvent(event);
  };

  // Attach event listeners to plane (or group) for pointer events
  group.addEventListener('pointerenter', handlePointerEnter);
  group.addEventListener('pointerleave', handlePointerLeave);
  group.addEventListener('pointerdown', handlePointerDown);
  group.addEventListener('pointerup', handlePointerUp);

  // Expose handlers for external assignment
  group.userData.handlers.select = undefined; // optional callback

  // Cleanup function
  group.userData.cleanup = () => {
    // Kill GSAP timelines
    if (hoverTimeline) hoverTimeline.kill();
    if (pressTween) pressTween.kill();
    // Remove event listeners
    group.removeEventListener('pointerenter', handlePointerEnter);
    group.removeEventListener('pointerleave', handlePointerLeave);
    group.removeEventListener('pointerdown', handlePointerDown);
    group.removeEventListener('pointerup', handlePointerUp);
    // Dispose resources
    geometry.dispose();
    edgeGeometry.dispose();
    material.dispose();
    edgeMaterial.dispose();
    if (texture) texture.dispose();
    // Remove children
    group.remove(plane);
  };

  return group;
}
